-- TEST DATABASE ONLY. Models the pre-existing schema documented by this repository.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE students(student_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),registration_no text UNIQUE NOT NULL,student_name text NOT NULL);
CREATE TABLE slots(slot_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slot_no integer,slot_name text,slot_status text DEFAULT 'ACTIVE');
CREATE TABLE compartments(compartment_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slot_id uuid REFERENCES slots,compartment_no integer,occupancy_status text DEFAULT 'EMPTY');
CREATE TABLE parcels(parcel_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tracking_id text UNIQUE NOT NULL,student_id uuid REFERENCES students,parcel_status text CHECK(parcel_status IN ('REGISTERED','STORED','COLLECTED')),payment_type text CHECK(payment_type IN ('PREPAID','COD')),payment_status text CHECK(payment_status IN ('PAID','PENDING','NOT_APPLICABLE')),compartment_id uuid REFERENCES compartments,created_at timestamptz DEFAULT now(),stored_at timestamptz,collected_at timestamptz);
CREATE TABLE hardware_devices(device_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),device_status text,last_seen_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE hardware_commands(command_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),device_id uuid REFERENCES hardware_devices,parcel_id uuid REFERENCES parcels,compartment_id uuid REFERENCES compartments,command_type text,command_status text CHECK(command_status IN ('PENDING','ACKNOWLEDGED','EXECUTED','FAILED')),acknowledged_at timestamptz,completed_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE hardware_events(event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),device_id uuid REFERENCES hardware_devices,source_event_key varchar(100),parcel_id uuid REFERENCES parcels,compartment_id uuid REFERENCES compartments,event_type text,processing_status text,occurred_at timestamptz,processed_at timestamptz,UNIQUE(device_id,source_event_key));
CREATE TABLE activity_logs(activity_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),parcel_id uuid REFERENCES parcels,student_id uuid REFERENCES students,slot_id uuid REFERENCES slots,compartment_id uuid REFERENCES compartments,device_id uuid REFERENCES hardware_devices,event_type text,details jsonb);
